{"content":"import { BreathingEstimator } from '../audio/dsp/breathing';
import { breathingEnvelope } from './signals';

function estimatorAt(bpm: number): BreathingEstimator {
  const estimator = new BreathingEstimator();
  for (const point of breathingEnvelope(bpm, 32)) {
    estimator.push(point.v, point.t);
  }
  return estimator;
}

describe('BreathingEstimator', () => {
  it.each([12, 24, 40])('оценивает %i уд/мин с допуском 3 уд/мин', (bpm) => {
    const estimate = estimatorAt(bpm).estimate(60_000);
    expect(estimate.valid).toBe(true);
    expect(Math.abs(estimate.bpm - bpm)).toBeLessThanOrEqual(3);
  });

  it('не засчитывает замер, если собака не была в покое д�� 40 секунд', () => {
    const estimate = estimatorAt(24).estimate(10_000);
    expect(estimate.valid).toBe(false);
    expect(estimate.reason).toBe('not_still');
  });

  it('помечает замер недостоверным в течение 2 секунд после лая', () => {
    const estimator = estimatorAt(24);
    estimator.noteBark(31_000);
    const estimate = estimator.estimate(60_000);
    expect(estimate.valid).toBe(false);
    expect(estimate.reason).toBe('bark_contamination');
  });

  it('возвращает insufficient_data на малом окне', () => {
    const estimator = new BreathingEstimator();
    for (const point of breathingEnvelope(24, 3)) estimator.push(point.v, point.t);
    const estimate = estimator.estimate(60_000);
    expect(estimate.valid).toBe(false);
    expect(estimate.reason).toBe('insufficient_data');
  });

  it('не выдаёт оценку для постоянного сигнала без дыхательной структуры', () => {
    const estimator = new BreathingEstimator();
    for (let t = 0; t <= 32_000; t += 50) estimator.push(-60, t);
    const estimate = estimator.estimate(60_000);
    expect(estimate.valid).toBe(false);
  });

  it('уверенность ниже, когда оценки расходятся', () => {
    const steady = estimatorAt(24).estimate(60_000);
    const noisy = new BreathingEstimator();
    for (let t = 0; t <= 32_000; t += 50) {
      // Сигнал с выраженной непериодичностью: оценки не сойдутся.
      noisy.push(-60 + 14 * Math.abs(Math.sin(t / 900)) + (t % 700), t);
    }
    const estimate = noisy.estimate(60_000);
    if (estimate.valid) expect(estimate.confidence).toBeLessThanOrEqual(steady.confidence);
  });
