{"content":"import { SoundEventDetector } from '../audio/dsp/events';
import type { AudioFeatures } from '../types';

const QUIET: AudioFeatures = {
  rmsDb: -60,
  peak: 0.001,
  zcr: 0.08,
  centroidHz: 600,
  flux: 0,
  bands: { low: 0.001, mid: 0.001, highMid: 0.001, high: 0.001 },
};

function bark(): AudioFeatures {
  return {
    rmsDb: -14,
    peak: 0.4,
    zcr: 0.1,
    centroidHz: 800,
    flux: 0.1,
    bands: { low: 0.02, mid: 0.2, highMid: 0.04, high: 0.005 },
  };
}

function broadband(): AudioFeatures {
  return {
    rmsDb: -20,
    peak: 0.2,
    zcr: 0.45,
    centroidHz: 2200,
    flux: 0.2,
    bands: { low: 0.05, mid: 0.05, highMid: 0.05, high: 0.05 },
  };
}

/** Прогоняет детектор по тишине, чтобы он выровнял порог по фоновому шуму. */
function warmUp(detector: SoundEventDetector): void {
  for (let t = 0; t < 4000; t += 50) detector.push(QUIET, t);
}

function feed(detector: SoundEventDetector, feature: AudioFeatures, frames: number, startAt: number) {
  const emitted = [];
  for (let i = 0; i < frames; i++) emitted.push(...detector.push(feature, startAt + i * 50));
  return emitted;
}

describe('SoundEventDetector', () => {
  it('выявляет лай после периода фонового шума', () => {
    const detector = new SoundEventDetector();
    warmUp(detector);

    feed(detector, bark(), 6, 10_000);
    const events = feed(detector, QUIET, 4, 10_300);

    const barks = events.filter((e) => e.kind === 'bark');
    expect(barks).toHaveLength(1);
    expect(barks[0].confidence).toBeGreaterThan(0.35);
    expect(barks[0].durationMs).toBeGreaterThanOrEqual(80);
  });

  it('не выдаёт ложных срабатываний на фоновом шуме', () => {
    const detector = new SoundEventDetector();
    warmUp(detector);
    const events = feed(detector, QUIET, 100, 10_000);
    expect(events.filter((e) => e.kind === 'bark')).toHaveLength(0);
  });

  it('не путает широкополосный шум с лаем', () => {
    const detector = new SoundEventDetector();
    warmUp(detector);
    const events = feed(detector, broadband(), 40, 10_000);
    expect(events.filter((e) => e.kind === 'bark')).toHaveLength(0);
  });

  it('игнорирует слишком короткий всплеск', () => {
    const detector = new SoundEventDetector();
    warmUp(detector);
    const events = feed(detector, bark(), 1, 10_000);
    expect(events.filter((e) => e.kind === 'bark')).toHaveLength(0);
  });

  it('выявляет серию всплесков как кашель', () => {
    const detector = new SoundEventDetector();
    warmUp(detector);

    const emitted = [];
    for (let burst = 0; burst < 3; burst++) {
      emitted.push(...feed(detector, broadband(), 3, 10_000 + burst * 500));
    }
    emitted.push(...feed(detector, QUIET, 20, 10_000 + 1500));

    const coughs = emitted.filter((e) => e.kind === 'cough');
    expect(coughs.length).toBeGreaterThanOrEqual(1);
    expect(coughs[0].durationMs).toBeLessThanOrEqual(2000);
  });

  it('выделяет визг по высокому спектральному центроиду', () => {
    const detector = new SoundEventDetector();
    warmUp(detector);

    const whine = { ...QUIET, rmsDb: -16, centroidHz: 2600, bands: { low: 0.002, mid: 0.004, highMid: 0.16, high: 0.02 } };
    feed(detector, whine, 6, 10_000);
    const events = feed(detector, QUIET, 6, 10_300);

    expect(events.filter((e) => e.kind === 'whine').length).toBeGreaterThanOrEqual(1);
  });

  it('сбрасывает состояние по reset', () => {
    const detector = new SoundEventDetector();
    warmUp(detector);
    detector.reset();
    expect(detector.currentNoiseFloorDb).toBe(-70);
  });
