{"content":"import { DEFAULT_LIMITS, canSpeak, canStartSession, createWelfareState, isQuietHours, registerSessionStart, registerVoice, volumeForStreak } from '../training/welfare';

const NOW = new Date('2026-10-12T14:00:00').getTime();

describe('welfare: лимиты сессий', () => {
  it('разрешает первые три сессии в час и блокирует четвёртую', () => {
    let state = createWelfareState(NOW);
    for (let i = 0; i < DEFAULT_LIMITS.maxSessionsPerHour; i++) {
      expect(canStartSession(state, NOW + i * 1000).allowed).toBe(true);
      state = registerSessionStart(state, NOW + i * 1000);
    }
    const blocked = canStartSession(state, NOW + 10_000);
    expect(blocked.allowed).toBe(false);
    expect(blocked.reason).toContain('лимит');
  });

  it('закрывает старт после дневного лимита минут', () => {
    let state = createWelfareState(NOW);
    state = { ...state, sessionMsToday: DEFAULT_LIMITS.maxSessionMinutesPerDay * 60_000 };
    const blocked = canStartSession(state, NOW);
    expect(blocked.allowed).toBe(false);
    expect(blocked.reason).toContain('дневной лимит');
  });
});

describe('welfare: голосовой бюджет', () => {
  it('выдерживает паузу между репликами', () => {
    let state = createWelfareState(NOW);
    expect(canSpeak(state, NOW, false).allowed).toBe(true);
    state = registerVoice(state, NOW);
    const tooSoon = canSpeak(state, NOW + 2000, false);
    expect(tooSoon.allowed).toBe(false);
    expect(canSpeak(state, NOW + DEFAULT_LIMITS.minGapBetweenVoiceMs + 1000, false).allowed).toBe(true);
  });

  it('глушит голос в тихие часы, но пропускает тревожные события', () => {
    const state = createWelfareState(NOW);
    expect(canSpeak(state, NOW, true).allowed).toBe(false);
    expect(canSpeak(state, NOW, true, true).allowed).toBe(true);
  });

  it('ограничивает число реплик в час', () => {
    let state = createWelfareState(NOW);
    for (let i = 0; i < DEFAULT_LIMITS.maxVoiceEventsPerHour; i++) {
      state = registerVoice(state, NOW + i * DEFAULT_LIMITS.minGapBetweenVoiceMs);
    }
    const blocked = canSpeak(state, NOW + DEFAULT_LIMITS.maxVoiceEventsPerHour * DEFAULT_LIMITS.minGapBetweenVoiceMs + 60_000, false);
    expect(blocked.allowed).toBe(false);
  });

  it('не повышает громкость при серии подкреплений', () => {
    const first = volumeForStreak(1);
    const second = volumeForStreak(2);
    const third = volumeForStreak(5);
    expect(second).toBeLessThan(first);
    expect(third).toBeLessThan(second);
    expect(first).toBeLessThanOrEqual(DEFAULT_LIMITS.maxVolume);
  });
});

describe('isQuietHours', () => {
  const at = (hour: number) => new Date(2026, 9, 12, hour, 0, 0).getTime();

  it('покрывает интервал через полночь', () => {
    expect(isQuietHours(at(23), 22, 7)).toBe(true);
    expect(isQuietHours(at(3), 22, 7)).toBe(true);
    expect(isQuietHours(at(12), 22, 7)).toBe(false);
  });

  it('работает с интервалом внутри суток', () => {
    expect(isQuietHours(at(13), 12, 14)).toBe(true);
    expect(isQuietHours(at(15), 12, 14)).toBe(false);
  });

  it('пустой интервал не блокирует ничего', () => {
    expect(isQuietHours(at(3), 5, 5)).toBe(false);
  });
