{"content":"import { applyLevel, createProgress, shouldReinforce, VARIABLE_RATIO } from '../training/reinforcement';

const T0 = 1_700_000_000_000;

describe('shouldReinforce', () => {
  it('всегда подкрепляет первую попытку по новой команде', () => {
    const decision = shouldReinforce({
      attempts: 1,
      successes: 1,
      reinforcements: 1,
      isNewCommand: true,
      levelChanged: false,
    });
    expect(decision.reinforce).toBe(true);
    expect(decision.reason).toBe('first_try');
  });

  it('всегда подкрепляет переход на новую ступень', () => {
    const decision = shouldReinforce({
      attempts: 6,
      successes: 6,
      reinforcements: 3,
      isNewCommand: false,
      levelChanged: true,
    });
    expect(decision.reinforce).toBe(true);
    expect(decision.reason).toBe('level_up');
  });

  it('применяет переменное подкрепление, а не каждое попадание', () => {
    let successes = 0;
    let reinforcements = 0;
    let reinforced = 0;

    for (let attempt = 0; attempt < 12; attempt++) {
      successes += 1;
      const decision = shouldReinforce({
        attempts: attempt + 1,
        successes,
        reinforcements,
        isNewCommand: false,
        levelChanged: false,
      });
      if (decision.reinforce) {
        reinforced += 1;
        reinforcements += 1;
      }
    }

    expect(reinforced).toBeGreaterThan(0);
    // Часть успехов остаётся без подкрепления — это суть переменного режима.
    expect(reinforced).toBeLessThan(successes);
    expect(VARIABLE_RATIO.every((v) => v >= 2)).toBe(true);
  });

  it('сообщает, сколько успехов осталось до подкрепления', () => {
    const decision = shouldReinforce({
      attempts: 3,
      successes: 1,
      reinforcements: 0,
      isNewCommand: false,
      levelChanged: false,
    });
    expect(decision.reinforce).toBe(false);
    expect(decision.untilNext).toBeGreaterThan(0);
  });
});

describe('лестница сложности', () => {
  it('поднимает уровень после трёх успехов подряд', () => {
    let progress = createProgress('sit', T0);
    for (let i = 0; i < 3; i++) progress = applyLevel(progress, true).progress;
    expect(progress.level).toBe(2);
    expect(progress.streak).toBe(0);
  });

  it('не опускается ниже первого уровня', () => {
    let progress = createProgress('sit', T0);
    for (let i = 0; i < 10; i++) progress = applyLevel(progress, false).progress;
    expect(progress.level).toBe(1);
  });

  it('не поднимается выше четвёртого уровня', () => {
    let progress = createProgress('sit', T0);
    for (let i = 0; i < 30; i++) progress = applyLevel(progress, true).progress;
    expect(progress.level).toBe(4);
  });

  it('откатывает уровень после двух провалов подряд', () => {
    let progress = createProgress('sit', T0);
    for (let i = 0; i < 3; i++) progress = applyLevel(progress, true).progress;
