{"content":"import { BACKUP_KEY, DEFAULT_SETTINGS, RETENTION_DAYS, SCHEMA_VERSION, STORAGE_KEY, loadPersisted, migrate, prune, savePersisted } from '../state/persistence';
import { createDefaultProfile } from '../device/profiles';

describe('migrate', () => {
  beforeEach(() => localStorage.clear());

  it('возвращает значения по умолчанию для пустого входа', () => {
    const state = migrate(null, createDefaultProfile());
    expect(state.version).toBe(SCHEMA_VERSION);
    expect(state.settings.llm.baseUrl).toBe(DEFAULT_SETTINGS.llm.baseUrl);
  });

  it('кладёт прежние данные в резервную копию при смене схемы', () => {
    migrate({ version: 999, sessions: [{ startedAt: 1 }] }, createDefaultProfile());
    expect(localStorage.getItem(BACKUP_KEY)).toContain('999');
  });

  it('сохраняет поля профиля при актуальной схеме', () => {
    const raw = { version: SCHEMA_VERSION, profile: { name: 'Лава' }, sessions: [], attempts: [], alerts: [], suspects: [], totalSteps: 5 };
    const state = migrate(raw, createDefaultProfile());
    expect(state.profile.name).toBe('Лава');
    expect(state.totalSteps).toBe(5);
  });

  it('дописывает отсутствующие настройки значениями по умолчанию', () => {
    const state = migrate({ version: SCHEMA_VERSION, settings: { voiceEnabled: false } }, createDefaultProfile());
    expect(state.settings.voiceEnabled).toBe(false);
    expect(state.settings.quietHoursStart).toBe(DEFAULT_SETTINGS.quietHoursStart);
    expect(state.settings.llm.timeoutMs).toBe(DEFAULT_SETTINGS.llm.timeoutMs);
  });

  it('переживает битые данные без исключения', () => {
    localStorage.setItem(STORAGE_KEY, '{не json');
    expect(() => loadPersisted(createDefaultProfile())).not.toThrow();
  });
});

describe('prune', () => {
  it('удаляет записи старше порога хранения', () => {
    const now = Date.now();
    const old = now - (RETENTION_DAYS + 1) * 86_400_000;
    const pruned = prune(
      {
        version: SCHEMA_VERSION,
        savedAt: now,
        profile: createDefaultProfile(),
        settings: DEFAULT_SETTINGS,
        progress: {} as never,
        sessions: [{ startedAt: old, endedAt: old + 1000, attempts: 1, successes: 1 }],
        attempts: [{ at: old, commandId: 'sit', success: true, level: 1, durationMs: 10, reinforced: true }],
        alerts: [{ id: 'x', at: old, severity: 'info', code: 'c', title: 't', detail: 'd', vetRecommended: false }],
        suspects: [{ at: old, durationSec: 70, confidence: 0.6, posture: 'stand', probability: 0.6 }],
        totalSteps: 10,
      },
      now,
    );
    expect(pruned.sessions).toHaveLength(0);
    expect(pruned.attempts).toHaveLength(0);
    expect(pruned.alerts).toHaveLength(0);
    expect(pruned.suspects).toHaveLength(0);
  });

  it('сохраняет свежие записи', () => {
    const now = Date.now();
    const state = loadPersisted(createDefaultProfile());
    const pruned = prune({ ...state, alerts: [{ id: 'x', at: now, severity: 'info', code: 'c', title: 't', detail: 'd', vetRecommended: false }] }, now);
    expect(pruned.alerts).toHaveLength(1);
  });
});

describe('savePersisted / loadPersisted', () => {
  beforeEach(() => localStorage.clear());

  it('сохраняет и читает обратно', () => {
    const state = loadPersisted(createDefaultProfile());
    savePersisted({ ...state, totalSteps: 777 });
    expect(loadPersisted(createDefaultProfile()).totalSteps).toBe(777);
  });

  it('не падает при недоступном хранилище', () => {
    const original = Storage.prototype.setItem;
    Storage.prototype.setItem = () => {
      throw new Error('quota');
    };
    try {
      const state = loadPersisted(createDefaultProfile());
      expect(savePersisted(state)).toBe(false);
    } finally {
      Storage.prototype.setItem = original;
    }
  });
