  voiceAvailable: true,
};

describe('parseAdvisorPayload', () => {
  it('разбирает корректный JSON', () => {
    const parsed = parseAdvisorPayload('{"title":"План","bullets":["Первое","Второе"]}');
    expect(parsed).toEqual({ title: 'План', bullets: ['Первое', 'Второе'] });
  });

  it('достаёт JSON из markdown-обёртки', () => {
    const parsed = parseAdvisorPayload('```json\n{"title":"План","bullets":["Один"]}\n```');
    expect(parsed?.bullets).toEqual(['Один']);
  });

  it('не доверяет модели: обрезает слишком длинные поля', () => {
    const parsed = parseAdvisorPayload(JSON.stringify({ title: 'A'.repeat(300), bullets: ['B'.repeat(400)] }));
    expect(parsed?.title.length).toBeLessThanOrEqual(90);
    expect(parsed?.bullets[0].length).toBeLessThanOrEqual(220);
  });

  it('ограничивает число пунктов', () => {
    const bullets = Array.from({ length: 20 }, (_, i) => `Пункт ${i}`);
    const parsed = parseAdvisorPayload(JSON.stringify({ title: 'План', bullets }));
    expect(parsed?.bullets.length).toBeLessThanOrEqual(6);
  });

  it('возвращает null на мусоре', () => {
    expect(parseAdvisorPayload('извините, я не знаю')).toBeNull();
    expect(parseAdvisorPayload('{"title":"План"}')).toBeNull();
    expect(parseAdvisorPayload('{"bullets":["Первый"]}')).toBeNull();
    expect(parseAdvisorPayload('{"title":"План","bullets":[]}')).toBeNull();
    expect(parseAdvisorPayload('{"title":"План","bullets":[1,2]}')).toBeNull();
  });

  it('выбрасывает нестроковые пункты, сохраняя остальные', () => {
    const parsed = parseAdvisorPayload('{"title":"План","bullets":["Хороший", 42, "Ещё хороший"]}');
    expect(parsed?.bullets).toEqual(['Хороший', 'Ещё хороший']);
  });
});

